protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph){
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null,
                Collections.emptyList(), Collections.emptyList(), 0.0);
    }
    // Build adjacency map from vertex to incident edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not in the graph");
        }
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }
    // Pick starting edge and vertex
    Iterator<E> it = tour.iterator();
    E startEdge = it.next();
    V startVertex = graph.getEdgeSource(startEdge);
    V currentVertex = startVertex;
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> remaining = new HashSet<>(tour);
    remaining.remove(startEdge);
    vertexList.add(startVertex);
    edgeList.add(startEdge);
    // Determine direction for startEdge
    V nextVertex = graph.getEdgeTarget(startEdge);
    currentVertex = nextVertex;
    vertexList.add(nextVertex);
    // Traverse remaining edges
    while (!remaining.isEmpty()) {
        List<E> candidates = adjacency.getOrDefault(currentVertex, Collections.emptyList());
        E nextEdge = null;
        for (E e : candidates) {
            if (!remaining.contains(e)) continue;
            V src = graph.getEdgeSource(e);
            V tgt = graph.getEdgeTarget(e);
            if (src.equals(currentVertex) && !tgt.equals(previousVertex(vertexList, vertexList.size() - 2))) {
                nextEdge = e;
                currentVertex = tgt;
                break;
            } else if (tgt.equals(currentVertex) && !src.equals(previousVertex(vertexList, vertexList.size() - 2))) {
                nextEdge = e;
                currentVertex = src;
                break;
            }
        }
        if (nextEdge == null) {
            throw new IllegalArgumentException("Edges do not form a continuous tour");
        }
        edgeList.add(nextEdge);
        vertexList.add(currentVertex);
        remaining.remove(nextEdge);
    }
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }
    return (GraphPath<V,E>) new GraphWalk<>(graph, vertexList.get(0),
            vertexList.get(vertexList.size() - 1), vertexList, edgeList, totalWeight);
