public int readTag() throws IOException {
    int b = read();
    if (b == -1) {
        // Reached EOF before reading any bytes.
        return 0;
    }

    int result = b & 0x7F;
    if ((b & 0x80) == 0) {
        // Single-byte tag.
        return result;
    }

    int shift = 7;
    while (shift < 32) {
        b = read();
        if (b == -1) {
            // Unexpected EOF while parsing varint.
            throw new IOException("Unexpected end of stream while parsing tag");
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }

    // If we reach here, the varint was too long.
    throw new IOException("Malformed varint: tag too long");
