        // When the end byte is not defined (negative) or invalid,
        // conform to the RFC that represents an unsatisfied byte-range request.
        if (endByte < 0 || endByte < startByte) {
            return String.format("bytes */%d", totalBytes);
        }
        return String.format("bytes %d-%d/%d", startByte, endByte, totalBytes);
    } catch (Exception e) {
        // Fall back in case of unexpected errors (e.g., IllegalStateException).
        return null;
    }
