public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> matchedSnapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IOException("Provided file is not a valid regular file.");
    }
    // Read all lines from the file
    List<String> lines;
    try {
        lines = java.nio.file.Files.readAllLines(file.toPath(), java.nio.charset.StandardCharsets.UTF_8);
    } catch (IOException e) {
        throw new IOException("Failed to read file: " + file.getAbsolutePath(), e);
    }
    // Iterate over each line, parse into a ThreadSnapshot, and filter by the provided time ranges
    for (String line : lines) {
        if (line == null || line.trim().isEmpty()) {
            continue;
        }
        ThreadSnapshot snapshot;
        try {
            // Assume ThreadSnapshot has a static parse method that returns null if parsing fails
            snapshot = ThreadSnapshot.parse(line.trim());
        } catch (Exception e) {
            // Skip malformed lines silently
            continue;
        }
        if (snapshot == null) {
            continue;
        }
        long timestamp = snapshot.getTimestamp(); // assume milliseconds from epoch
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start = range.getStartMillis(); // assume start in milliseconds
            long end = range.getEndMillis();     // assume end in milliseconds
            if (timestamp >= start && timestamp <= end) {
                matchedSnapshots.add(snapshot);
                break; // move to next snapshot
            }
        }
    }
    return matchedSnapshots;
