public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    // Basic validation: if file does not exist or timeRanges is null, return empty list
    if (file == null || !file.exists() || timeRanges == null) {
        return result;
    }

    // Acquire all snapshots from the file; we assume a helper method exists
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);
    if (allSnapshots == null) {
        return result;
    }

    for (ThreadSnapshot snapshot : allSnapshots) {
        if (snapshot == null) {
            // Skip corrupted or null entries
            continue;
        }
        // Assume ThreadSnapshot has a method getTimestamp() that returns the snapshot time in millis
        long snapshotTime;
        try {
            snapshotTime = snapshot.getTimestamp();
        } catch (Exception e) {
            // If getTimestamp is not available or throws, skip this snapshot
            continue;
        }

        // Check if snapshotTime falls within any of the provided time ranges
        boolean inRange = false;
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (range == null) {
                continue;
            }
            long start;
            long end;
            // Attempt to fetch the range boundaries using expected getter names
            try {
                start = range.getStartMillis(); // we expect start getter
                end = range.getEndMillis();     // we expect end getter
            } catch (Exception e) {
                // If getters not available, try reflection to fallback
                start = 0L;
                end = Long.MAX_VALUE;
                try {
                    Object s = range.getClass().getMethod("getStart").invoke(range);
                    Object e = range.getClass().getMethod("getEnd").invoke(range);
                    if (s instanceof Number) {
                        start = ((Number) s).longValue();
                    }
                    if (e instanceof Number) {
                        end = ((Number) e).longValue();
                    }
                } catch (Exception ignored) {
                }
            }

            if (snapshotTime >= start && snapshotTime <= end) {
                inRange = true;
                break;
            }
        }

        if (inRange) {
            result.add(snapshot);
        }
    }

