public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("timeRanges must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File does not exist or is not a regular file: " + file);
    }

    List<ThreadSnapshot> snapshots = new ArrayList<>();

    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            // Assume the line starts with a timestamp followed by a comma
            int commaIndex = line.indexOf(',');
            if (commaIndex == -1) {
                // Invalid format; skip line
                continue;
            }

            String tsString = line.substring(0, commaIndex).trim();
            long timestamp;
            try {
                timestamp = Long.parseLong(tsString);
            } catch (NumberFormatException e) {
                // Malformed timestamp; skip line
                continue;
            }

            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                long start = range.getStartMillis();
                long end = range.getEndMillis();
                if (timestamp >= start && timestamp <= end) {
                    inRange = true;
                    break;
                }
            }

            if (!inRange) {
                continue;
            }

            // Parse the snapshot; we assume ThreadSnapshot has a static parse method
            try {
                ThreadSnapshot snapshot = ThreadSnapshot.parse(line);
                snapshots.add(snapshot);
            } catch (Exception e) {
                // If parsing fails, skip this line but continue processing
            }
        }
    }

    return snapshots;
